'use strict';

function briefPage() {
  return `<div class="brief-layout"><section class="brief-intro">${header('Ваш личный AI-консультант','Хорошее событие.<br><em>С вашего рассказа.</em>','Расскажите, что вы задумали. Мы превратим пожелания в понятные условия и поможем найти подходящих людей.')}<div class="small-steps"><p><span>01</span>Напишите или надиктуйте идею</p><p><span>02</span>Проверьте распознанные условия</p><p><span>03</span>Сравните до трёх вариантов</p></div><p class="quiet-note">${icon('shield')}Вы управляете выбором. Никаких автоматических бронирований.</p></section>
  <section class="brief-editor"><form id="brief-form"><div class="editor-heading"><span class="eyebrow">Начнём с вашей идеи</span>${icon('sparkles')}</div><label for="brief">Какое событие вы планируете?</label><textarea id="brief" name="text" rows="6" maxlength="2000" required placeholder="Например, камерная свадьба в Алматы 10 октября. Ищу фотографа до 300 000 ₸. Хочется живых, естественных кадров.">${esc(rawBrief)}</textarea>${voiceControls()}<p class="hint">Укажите город, дату, формат, подрядчика и бюджет. Остальное уточним.</p>${!options.ai_enabled ? '<p class="service-note">AI-консультант пока недоступен. Вы можете сразу выбрать условия вручную.</p>' : ''}<div class="actions"><button class="btn btn-primary" type="submit" ${!options.ai_enabled ? 'disabled' : ''}>Понять запрос ${icon('arrow')}</button>${button('Указать условия','event',false,'sliders')}</div><p class="privacy-note">Описание и запись отправляются в OpenAI. Не указывайте контакты и личные данные гостей.</p></form></section></div>
  <section class="demo-examples" aria-label="Примеры запросов"><span class="eyebrow">Попробуйте на примере</span><div class="example-list"><button data-example="hosts"><span>Корпоратив в Алматы</span><small>Ведущий · 6 октября</small>${icon('arrow')}</button><button data-example="rare"><span>Свадьба в Астане</span><small>Флорист · 1 октября</small>${icon('arrow')}</button><button data-example="empty"><span>А если дата занята?</span><small>Найдём ближайшие варианты</small>${icon('arrow')}</button></div></section>`;
}

function eventFields() {
  return `<div class="event-fields"><div class="field-row">${selectField('Город','city',options.cities,state.city)}${selectField('Формат мероприятия','event_type',options.event_types,state.event_type)}</div>${selectField('Кто вам нужен','category',options.categories,state.category)}${calendarField()}</div>`;
}
function eventPage() {
  return header('01 / Ваше событие','Начнём с <em>деталей.</em>','Выберите подрядчика и посмотрите, в какие дни больше свободных вариантов.') + `<form id="event-form" data-query class="content-form"><div class="form-card">${eventFields()}</div><div class="actions">${button('К описанию','brief',false,'back')}<button type="submit" class="btn btn-primary">Указать условия ${icon('arrow')}</button></div></form>`;
}
function preferenceFields() {
  return `<div class="field"><label for="budget_kzt">Максимальный бюджет, ₸</label><input id="budget_kzt" name="budget_kzt" type="number" min="1" max="1000000000" step="1" required value="${state.budget_kzt ?? ''}" aria-describedby="budget-hint"><p class="hint" id="budget-hint">На одного подрядчика за мероприятие. Цена «от» не гарантирует итоговую стоимость.</p></div><div class="field-row"><div class="field"><label for="duration_hours">Часы работы подрядчика</label><input id="duration_hours" name="duration_hours" type="number" min="0.1" max="168" step="any" placeholder="Не важно" value="${state.duration_hours ?? ''}"></div>${selectField('Язык работы','language',options.languages,state.language,false)}</div>`;
}
function wishFields() {
  return `<fieldset data-wishes class="wish-fieldset"><legend>Пожелания к стилю — необязательно</legend><p class="hint">Влияют на порядок, но не являются гарантией услуги. Выберите то, что действительно важно.</p>${!options.semantic_enabled ? '<p class="hint">Смысловой подбор пока недоступен: сейчас результаты будут упорядочены по начальной цене.</p>' : ''}<div class="wish-grid">${options.wishes.map(w => `<label class="wish-option"><input type="checkbox" name="wish" value="${w.id}" ${state.wishes.includes(w.id) ? 'checked' : ''}><span>${esc(w.label)}</span></label>`).join('')}</div></fieldset>`;
}
function unresolvedFields() {
  if (!reviewRequirements.length) return '';
  return `<section id="requirements-review" class="form-card unresolved" aria-labelledby="requirements-title"><div class="eyebrow">Перед подбором</div><h2 id="requirements-title">Нужно ваше решение</h2><p>AI выделил детали, которые нельзя надёжно проверить по каталогу. Уточните описание или отметьте только те пункты, без проверки которых согласны продолжить.</p><div class="requirements-list">${reviewRequirements.map((text,i)=>`<label class="requirement-item"><span class="requirement-text">${esc(text)}</span><span class="requirement-choice"><input type="checkbox" name="ignored_requirement" value="${i}" ${state.unverified_requirements.includes(text) ? '' : 'checked'}><span>Не проверять этот пункт при подборе</span></span></label>`).join('')}</div><p id="requirements-status" role="status">${state.unverified_requirements.length ? 'Осталось уточнить: '+state.unverified_requirements.length+'.' : 'Эти условия исключены из проверки по вашему выбору.'}</p>${button('Уточнить описание','brief',false,'back')}<p class="hint">Город, дата, формат, категория и бюджет всё равно обязательны. Если уточняете описание, исходный текст сохранён.</p></section>`;
}
function ignoredRequirementsNote() {
  const ignored = reviewRequirements.filter(text => !state.unverified_requirements.includes(text));
  return ignored.length ? `<details class="ignored-note"><summary>Не проверялись по вашему выбору: ${ignored.length}</summary><ul>${ignored.map(text=>`<li>${esc(text)}</li>`).join('')}</ul><p>Подбор не подтверждает выполнение этих условий.</p></details>` : '';
}
function preferencesPage() {
  return header('02 / Условия','Что для вас <em>важно?</em>','Язык и длительность станут строгими условиями, если вы их укажете.') + `<form id="preferences-form" data-query class="content-form">${unresolvedFields()}<div class="form-card">${preferenceFields()}</div>${wishFields()}<div class="actions">${button('Назад','event',false,'back')}<button type="submit" class="btn btn-primary">Проверить параметры ${icon('arrow')}</button></div></form>`;
}
function reviewPage() {
  return header('03 / Подтверждение','Всё сходится? <em>Подберём.</em>','Проверьте распознанные условия. Любое поле можно исправить перед поиском.') + `${rawBrief ? `<details class="source-brief"><summary>Исходное описание</summary><p>${esc(rawBrief)}</p>${button('Уточнить описание','brief',false,'back')}</details>` : ''}<form id="review-form" data-query>${unresolvedFields()}<div class="summary-grid"><section class="summary-card"><h2>Ваше мероприятие</h2>${eventFields()}</section><section class="summary-card"><h2>Ваш подрядчик</h2>${preferenceFields()}</section></div>${wishFields()}<div class="review-note">${icon('sparkles')}<p><strong>До трёх вариантов, с конкретными причинами.</strong>Сначала проверим условия и занятость, затем учтём выбранные пожелания.</p></div><div class="actions">${button('К описанию','brief',false,'back')}<button type="submit" class="btn btn-primary">Подтвердить и подобрать ${icon('arrow')}</button></div></form>`;
}
function chips() {
  const values = [state.city,dateLabel(state.event_date),state.event_type,state.category,'До ' + money(state.budget_kzt)];
  if (state.duration_hours) values.push(state.duration_hours + ' ч работы');
  if (state.language) values.push(state.language);
  for (const id of state.wishes) values.push(options.wishes.find(w => w.id === id)?.label || id);
  return `<div class="chips">${values.map(v => `<span class="chip">${esc(v)}</span>`).join('')}</div>`;
}
function provenance(p) {
  return `<span class="synthetic">${p.data_origin === 'team' ? (p.synthetic ? 'Синтетический профиль команды' : 'Добавлено командой') : p.synthetic ? 'Синтетический профиль организаторов' : 'Исходный каталог · анонимизировано'}</span>${p.price_imputed ? '<p class="hint">Цена дополнена при подготовке данных.</p>' : ''}${p.city_imputed ? '<p class="hint">Город дополнен при подготовке данных.</p>' : ''}`;
}
const initials = p => p.anon_name.split(' ').slice(0,2).map(x => x[0]).join('');
function card(p,i) {
  return `<article class="contractor-card"><div class="contractor-top"><div class="avatar ${i % 2 ? 'secondary' : ''}" aria-hidden="true">${esc(initials(p))}</div><div><h2>${esc(p.anon_name)}</h2><div class="meta">${esc(p.matched_category)} · ${esc(p.city)}</div></div></div>${provenance(p)}<div class="price"><small>От </small>${money(p.price_from_kzt)}</div><p class="meta">За мероприятие · начальная цена</p><div class="available">${icon('check')}Нет отметки о занятости ${dateLabel(state.event_date)}</div><div class="match-reason"><strong>${icon('sparkles')}ПОЧЕМУ В ПОДБОРКЕ</strong><p>${esc(p.explanation)}</p></div>${button('Посмотреть профиль','profile/' + p.id)}</article>`;
}
function resultsPage() {
  const r = activeResults;
  return `<div class="result-heading"><div>${header('Ваша подборка',`Подходящих вариантов: <em>${r.cards.length}</em>`,'Выбор из исходного каталога по подтверждённым условиям.')}</div>${button('Изменить условия','review',false,'sliders')}</div>${chips()}${ignoredRequirementsNote()}<div class="result-note">${icon('info')}<span>${esc(r.message)}</span></div>${r.notice ? `<p class="result-note">${esc(r.notice)}</p>` : ''}<p class="result-note">Порядок: ${r.ranking === 'semantic' ? 'близость к вашим пожеланиям, затем начальная цена' : 'начальная цена'}.</p>${r.date_change ? `<p class="review-note">${esc(r.date_change)}</p>` : ''}<div class="contractor-grid">${r.cards.map(card).join('')}</div>${alternativesPage()}<p class="result-bottom">Цены «от» не являются окончательным предложением. Сведения и заявления взяты из каталога; бронирование не выполняется.</p>`;
}
function emptyPage() {
  const absent = activeResults.status === 'category_unavailable';
  const otherDates = activeResults.date_alternatives?.some(p => p.dates.length);
  const nearby = activeResults.nearby_alternatives?.length;
  return `<section class="empty-page ${nearby || otherDates ? 'with-alternatives' : ''}"><div class="empty-icon">${icon(absent ? 'search' : 'calendar')}</div>${header('Результат подбора',absent ? 'В городе нет<br><em>такой категории.</em>' : otherDates ? 'На эту дату занято.<br><em>Есть другие дни.</em>' : 'По этим условиям<br><em>совпадений нет.</em>','Условия сохранены — их можно изменить и повторить поиск.')}${chips()}${ignoredRequirementsNote()}<div class="summary-card"><p>${esc(activeResults.message)}</p></div>${activeResults.date_change ? `<p class="review-note">${esc(activeResults.date_change)}</p>` : ''}${activeResults.notice ? `<p class="hint">${esc(activeResults.notice)}</p>` : ''}<div class="actions">${button('Изменить условия','review',true,'sliders')}${button('Изменить дату','event',false,'calendar')}</div></section>${nearby ? nearbyAlternativesPage() : alternativesPage()}`;
}
function profilePage(id) {
  const p = activeResults?.cards.find(p => p.id === id);
  if (!p) { navigate('review'); return ''; }
  return `${button('К подборке','results',false,'back')}<div class="profile-layout"><article class="profile-main"><div class="profile-head"><div class="avatar" aria-hidden="true">${esc(initials(p))}</div><div><h1>${esc(p.anon_name)}</h1><p class="meta">${esc(p.categories.join(' · '))} · ${esc(p.city)}</p>${provenance(p)}</div></div><div class="match-reason"><strong>ПОЧЕМУ В ПОДБОРКЕ</strong><p>${esc(p.explanation)}</p></div><h2>Описание из каталога</h2><p>${esc(p.description)}</p><p class="hint">Текст профиля содержит заявления автора; награды и отзывы отдельно не проверялись. Для строгих условий используются поля ниже.</p><h2>Условия работы</h2><dl class="facts"><div><dt>Форматы</dt><dd>${esc(p.event_formats.join(' · '))}</dd></div><div><dt>Языки</dt><dd>${esc(p.languages.join(' · '))}</dd></div><div><dt>Длительность</dt><dd>${p.max_hours === null ? 'Присутствие на площадке не требуется' : 'До ' + p.max_hours + ' ч на площадке'}</dd></div></dl></article><aside class="profile-aside"><div class="eyebrow">Условия предложения</div><div class="price">От ${money(p.price_from_kzt)}</div><p>За мероприятие, окончательная цена может отличаться.</p><div class="available">${icon('check')}Нет отметки о занятости ${dateLabel(state.event_date)}</div><p>Бюджет: ${money(state.budget_kzt)}.</p>${button('К подборке','results',false,'back')}</aside></div>`;
}

function homePage() {
  const occasions = [['свадьба','heart','Ваш особенный день'],['корпоратив','sparkles','Команда, которая ближе'],['день рождения','gift','Повод собраться вместе']].filter(([name]) => options.event_types.includes(name));
  return `<section class="home-hero"><div class="hero-copy"><div class="eyebrow">События начинаются с людей</div><h1>Ваше событие.<br>Ваша атмосфера.<br><em>Ваши люди.</em></h1><p class="intro">Найдите тех, кто поймёт вашу идею. Расскажите о событии — мы подберём подрядчиков по условиям и объясним каждый выбор.</p><div class="actions">${button('Найти своих людей','brief',true)}${button('Сначала выбрать дату','event',false,'calendar')}</div><div class="hero-footnote"><span class="mini-star" aria-hidden="true">✳</span><span>Меньше поисков.<br>Больше предвкушения.</span></div></div>
  <div class="event-art" aria-hidden="true"><div class="art-orbit"></div><div class="table-scene"><span class="chair chair-one"></span><span class="chair chair-two"></span><span class="chair chair-three"></span><span class="chair chair-four"></span><div class="event-table"><span class="plate plate-one"></span><span class="plate plate-two"></span><span class="plate plate-three"></span><span class="plate plate-four"></span><div class="table-flower"><i></i><i></i><i></i><i></i><i></i></div><span class="table-line line-one"></span><span class="table-line line-two"></span></div></div><span class="art-note">Для встреч,<br>которые остаются <em>с нами.</em></span><span class="art-star">✳</span></div></section>
  <section class="occasion-section" aria-labelledby="occasion-title"><div class="section-heading"><div><span class="eyebrow">Любой повод — ваш</span><h2 id="occasion-title">Что будем <em>праздновать?</em></h2></div><p>От камерного ужина до большого события.</p></div><div class="occasion-list">${occasions.map(([name,ico,caption],i)=>`<button data-occasion="${esc(name)}"><span class="occasion-number">0${i+1}</span><span class="occasion-icon">${icon(ico)}</span><span><strong>${esc(name[0].toUpperCase()+name.slice(1))}</strong><small>${caption}</small></span>${icon('arrow')}</button>`).join('')}</div></section>
  <section class="how-section" aria-labelledby="how-title"><div class="how-heading"><span class="eyebrow">Всё начинается с разговора</span><h2 id="how-title">От идеи<br>к <em>своим людям.</em></h2>${button('Попробовать','brief',false,'arrow')}</div><div class="how-list"><article><span>01</span><div><h3>Расскажите о событии</h3><p>Текстом или голосом. Город, дата, бюджет и атмосфера, которую вы хотите создать.</p></div></article><article><span>02</span><div><h3>Проверьте детали</h3><p>Исправьте условия, посмотрите занятость в календаре и подтвердите запрос.</p></div></article><article><span>03</span><div><h3>Сравните подходящих</h3><p>До трёх вариантов с фактами из каталога. Если дата занята — предложим соседние свободные дни.</p></div></article></div></section>`;
}

function alternativesPage() {
  const alternatives = activeResults?.date_alternatives || [];
  if (!alternatives.length) return '';
  return `<section class="date-alternatives" aria-labelledby="alternatives-title"><div class="section-heading"><div><span class="eyebrow">Если дата может измениться</span><h2 id="alternatives-title">Подходят по условиям.<br><em>Заняты ${dateLabel(state.event_date)}.</em></h2></div>${icon('calendar')}</div><p class="intro">Эти подрядчики не вошли в рекомендации на выбранный день. Ниже — их ближайшие даты без отметки о занятости. Выберите дату, затем подтвердите условия заново.</p><div class="alternative-list">${alternatives.map(p=>`<article class="alternative-row"><div class="alternative-person"><div class="avatar" aria-hidden="true">${esc(initials(p))}</div><div><h3>${esc(p.anon_name)}</h3><p class="meta">${esc(state.category)} · ${esc(p.city)} · от ${money(p.price_from_kzt)}</p>${provenance(p)}</div></div><div class="alternative-dates">${p.dates.length ? p.dates.map(d=>`<button type="button" class="date-chip" data-alternative-date="${esc(d)}" aria-label="Выбрать ${dateLabel(d)}: ${esc(p.anon_name)}">${icon('calendar')}${dateLabel(d)}${icon('arrow')}</button>`).join('') : '<p class="hint">В доступном календаре до 31 декабря свободных дат нет.</p>'}</div></article>`).join('')}</div><p class="hint">Остальные условия сохраняются. Даты до 23 сентября и после 31 декабря 2026 не проверены.</p></section>`;
}

function nearbyAlternativesPage() {
  const alternatives = activeResults.nearby_alternatives;
  return `<section class="date-alternatives nearby-alternatives" aria-labelledby="nearby-title"><div class="section-heading"><div><span class="eyebrow">Если готовы пересмотреть условия</span><h2 id="nearby-title">Ближайшие <em>варианты.</em></h2></div></div><p class="intro">Эти подрядчики не подходят под исходный запрос полностью. Для каждого показаны все несовпадения. Условия сохранены: вы сами решаете, что изменить.</p><p class="hint">Сначала меньше несовпадений; при равенстве — ваш город, меньшая доплата, ближайшая дата и цена. Другой город не означает возможность выезда.</p><div class="contractor-grid">${alternatives.map(p => {
    const booked = p.differences.some(d => d.field === 'event_date');
    return `<article class="contractor-card nearby-card"><div class="contractor-top"><div class="avatar" aria-hidden="true">${esc(initials(p))}</div><div><h3>${esc(p.anon_name)}</h3><p class="meta">${esc(state.category)} · ${esc(p.city)}</p></div></div>${provenance(p)}<div class="price"><small>От </small>${money(p.price_from_kzt)}</div><p class="hint">Начальная цена, не окончательная стоимость.</p><p class="nearby-evidence">Из описания: «${esc(p.evidence)}»</p><div class="nearby-differences"><strong>Что не совпало</strong><ul>${p.differences.map(d => `<li>${esc(d.message)}</li>`).join('')}</ul></div>${booked ? `<p class="hint">${p.dates.length ? 'Ближайшие даты без отметки о занятости:' : 'Свободных дат в доступном календаре нет.'}</p><div class="alternative-dates">${p.dates.map(d => `<button type="button" class="date-chip" data-alternative-date="${esc(d)}" aria-label="Выбрать ${dateLabel(d)} для пересмотра условий: ${esc(p.anon_name)}">${icon('calendar')}${dateLabel(d)}</button>`).join('')}</div>${p.differences.length > 1 && p.dates.length ? '<p class="hint">Смена даты не устраняет остальные несовпадения выше.</p>' : ''}` : `<p class="available">${icon('calendar')}На ${dateLabel(state.event_date)} занятость не отмечена.</p>`}<button type="button" class="btn" data-nearby-review aria-label="Пересмотреть условия для ${esc(p.anon_name)}">${icon('sliders')}Пересмотреть условия</button></article>`;
  }).join('')}</div><p class="hint">Календарь известен только с 23 сентября по 31 декабря 2026. Выбор даты открывает проверку условий; бронирование не выполняется.</p></section>`;
}
